import { test } from 'node:test';
import assert from 'node:assert/strict';
import { tarefasEmFila } from './solution.mjs';

test('devolve os nomes na ordem em que os timers disparam', async () => {
  const tarefas = [
    { nome: 'lenta', ms: 9 },
    { nome: 'rapida', ms: 2 },
    { nome: 'media', ms: 5 },
  ];
  assert.deepEqual(await tarefasEmFila(tarefas), ['rapida', 'media', 'lenta']);
});

test('funciona com tarefas de mesmo tempo', async () => {
  const tarefas = [
    { nome: 'a', ms: 3 },
    { nome: 'b', ms: 3 },
  ];
  assert.deepEqual((await tarefasEmFila(tarefas)).sort(), ['a', 'b']);
});

test('lista vazia devolve lista vazia', async () => {
  assert.deepEqual(await tarefasEmFila([]), []);
});

test('rejeita quando tarefas não é uma lista', async () => {
  await assert.rejects(() => tarefasEmFila('nada'), /lista/);
});

solutionCode:
export function tarefasEmFila(tarefas) {
  return new Promise((resolve, reject) => {
    if (!Array.isArray(tarefas)) {
      reject(new Error('tarefas deve ser uma lista'));
      return;
    }
    const nomes = [];
    let pendentes = tarefas.length;
    if (pendentes === 0) {
      resolve([]); // nada agendado: resolve já
      return;
    }
    for (const tarefa of tarefas) {
      // cada timer empurra o nome quando dispara
      setTimeout(() => {
        nomes.push(tarefa.nome);
        pendentes -= 1;
        // só resolve quando o ÚLTIMO timer disparar
        if (pendentes === 0) {
          resolve(nomes);
        }
      }, tarefa.ms);
    }
  });
}
